        rmin,rmax=min(r for r,c in pts),max(r for r,c in pts)
        cmin,cmax=min(c for r,c in pts),max(c for r,c in pts)
        ph,pw=rmax-rmin+1,cmax-cmin+1
        pat=[[grid[rmin+i][cmin+j]==color for j in range(pw)] for i in range(ph)]
        # rectangular zero canvas reached by 4-connectivity
        comp=set(pts); q=list(pts)
        while q:
            r,c=q.pop()
            for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if 0<=y<H and 0<=x<W and g[y][x] in (0,color) and (y,x) not in comp:
                    comp.add((y,x));q.append((y,x))
        a,b=min(r for r,c in comp),max(r for r,c in comp)
        d,e=min(c for r,c in comp),max(c for r,c in comp)
        for r in range(a,b+1):
            for c in range(d,e+1):
                if g[r][c]==0 and pat[(r-rmin)%ph][(c-cmin)%pw]:g[r][c]=color
    return g

