def transform(grid):
    # Propagate each colored seed as a periodic tile across the adjoining zero canvas.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for color in range(1, 10):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not pts:
            continue
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        ph, pw = r1-r0+1, c1-c0+1
        motif = [[grid[r0+i][c0+j] == color for j in range(pw)] for i in range(ph)]
        seen = set(pts)
        stack = list(pts)
        while stack:
            r, c = stack.pop()
            for y, x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if 0 <= y < h and 0 <= x < w and grid[y][x] in (0,color) and (y,x) not in seen:
                    seen.add((y,x)); stack.append((y,x))
        top, bottom = min(r for r,c in seen), max(r for r,c in seen)
        left, right = min(c for r,c in seen), max(c for r,c in seen)
        for r in range(top,bottom+1):
            for c in range(left,right+1):
                if out[r][c] == 0 and motif[(r-r0)%ph][(c-c0)%pw]:
                    out[r][c] = color
    return out
